// Normalização e Classificação de Entrada
const body = $input.first().json.body || $input.first().json;
let url = body.url ? body.url.trim() : null;
let text = body.text ? body.text.trim() : null;
let fileBase64 = body.file_base64 || null;
let fileMime = body.file_mime || 'text/plain';

let sourceType = 'note';
if (url) {
  if (/instagram\.com\/(reel|p)\//i.test(url)) {
    sourceType = 'reel';
  } else if (/youtu(be\.com|\.be)/i.test(url)) {
    sourceType = 'youtube';
  } else if (/tiktok\.com/i.test(url)) {
    sourceType = 'tiktok';
  } else if (/\.pdf($|\?)/i.test(url)) {
    sourceType = 'pdf';
  } else {
    sourceType = 'article';
  }
} else if (fileBase64) {
  if (/audio/i.test(fileMime)) {
    sourceType = 'audio';
  } else if (/pdf/i.test(fileMime)) {
    sourceType = 'pdf';
  } else {
    sourceType = 'document';
  }
}

return [{
  json: {
    url,
    text,
    fileBase64,
    fileMime,
    sourceType,
    rawInput: url || text || 'Arquivo binário recebido'
  }
}];

