// Extrai o JSON gerado pelo Gemini
const geminiResponse = $input.first().json;
let parsed = {};
try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = {
    title: 'Nota Capturada (' + new Date().toLocaleDateString('pt-BR') + ')',
    summary: 'Processado automaticamente',
    key_takeaways: [],
    action_items: [],
    entities: [],
    raw_content: '',
    tags: ['inbox']
  };
}

const prev = $('Classificar Entrada').first().json;

return [{
  json: {
    title: parsed.title || 'Sem título',
    summary: parsed.summary || '',
    key_takeaways: parsed.key_takeaways || [],
    action_items: parsed.action_items || [],
    entities: parsed.entities || [],
    raw_content: parsed.raw_content || '',
    tags: parsed.tags || ['geral'],
    stage: 'budding',
    source_type: prev.sourceType,
    source_url: prev.url,
    text_for_embedding: (parsed.title || '') + ' ' + (parsed.summary || '') + ' ' + (parsed.tags || []).join(' ') + ' ' + (parsed.entities || []).join(' ')
  }
}];

